226	fn bfs_reachable(seed: usize, neighbors: &[Vec<usize>]) -> Vec<usize> {
227	    let mut marked = vec![false; neighbors.len()];
228	    marked[seed] = true;
229	    let mut reachable = vec![seed];
230	    let mut queue = VecDeque::new();
231	    queue.push_back(seed);
232	    while let Some(node) = queue.pop_front() {
233	        for &next in &neighbors[node] {
234	            if !marked[next] {
235	                marked[next] = true;
236	                reachable.push(next);
237	                queue.push_back(next);
238	            }
239	        }
240	    }
241	    reachable
242	}
243	
244	fn bfs_eccentricity(start: usize, neighbors: &[Vec<usize>]) -> (usize, Vec<usize>) {
245	    let mut marked = vec![false; neighbors.len()];
246	    marked[start] = true;
247	    let mut level = vec![start];
248	    let mut depth = 0;
249	    loop {
250	        let mut next_level = Vec::new();
251	        for &node in &level {
252	            for &next in &neighbors[node] {
253	                if !marked[next] {
254	                    marked[next] = true;
255	                    next_level.push(next);
256	                }
257	            }
258	        }
259	        if next_level.is_empty() {
260	            return (depth, level);
261	        }
262	        depth += 1;
263	        level = next_level;
264	    }
265	}
266	
267	fn min_by_degree_then_index(nodes: &[usize], degrees: &[usize]) -> Option<usize> {
268	    nodes
269	        .iter()
270	        .copied()
271	        .min_by_key(|&node| (degrees[node], node))
272	}
273	
274	fn pseudo_peripheral_start(seed: usize, neighbors: &[Vec<usize>], degrees: &[usize]) -> usize {
275	    let component = bfs_reachable(seed, neighbors);
276	    let mut candidate = min_by_degree_then_index(&component, degrees).unwrap_or(seed);
277	    let (mut candidate_eccentricity, mut last_level) = bfs_eccentricity(candidate, neighbors);
278	    loop {
279	        let next = match min_by_degree_then_index(&last_level, degrees) {
280	            Some(node) => node,
281	            None => break,
282	        };
283	        let (next_eccentricity, next_last_level) = bfs_eccentricity(next, neighbors);
284	        if next_eccentricity > candidate_eccentricity {
285	            candidate = next;
286	            candidate_eccentricity = next_eccentricity;
287	            last_level = next_last_level;
288	        } else {
289	            break;
290	        }
291	    }
292	    candidate
293	}
