295	/// Deterministic reverse Cuthill–McKee, ported from `sparse_direct` (its
296	/// tie-break rules): `order[k]` is the original index of the k-th ordered node.
297	/// Adjacency indices must be in range (internal data).
298	pub fn reverse_cuthill_mckee(adjacency: &[Vec<usize>]) -> Vec<usize> {
299	    let node_count = adjacency.len();
300	    let mut neighbors: Vec<Vec<usize>> = vec![Vec::new(); node_count];
301	    for (node, raw) in adjacency.iter().enumerate() {
302	        for &other in raw {
303	            debug_assert!(other < node_count);
304	            if other != node {
305	                neighbors[node].push(other);
306	                neighbors[other].push(node);
307	            }
308	        }
309	    }
310	    for list in &mut neighbors {
311	        list.sort_unstable();
312	        list.dedup();
313	    }
314	    let degrees: Vec<usize> = neighbors.iter().map(Vec::len).collect();
315	    for list in &mut neighbors {
316	        list.sort_by_key(|&node| (degrees[node], node));
317	    }
318	    let mut visited = vec![false; node_count];
319	    let mut order = Vec::with_capacity(node_count);
320	    for seed in 0..node_count {
321	        if visited[seed] {
322	            continue;
323	        }
324	        let start = pseudo_peripheral_start(seed, &neighbors, &degrees);
325	        visited[start] = true;
326	        let mut queue = VecDeque::new();
327	        queue.push_back(start);
328	        while let Some(node) = queue.pop_front() {
329	            order.push(node);
330	            for &next in &neighbors[node] {
331	                if !visited[next] {
332	                    visited[next] = true;
333	                    queue.push_back(next);
334	                }
335	            }
336	        }
337	    }
338	    order.reverse();
339	    order
340	}
