342	/// The free DOFs, their RCM order and skyline (integer data, per source).
343	#[derive(Debug, Clone, PartialEq, Eq)]
344	pub(crate) struct Ordering {
345	    /// Free global DOFs, ascending (a free position indexes this list).
346	    pub(crate) free: Vec<usize>,
347	    /// Global DOF → free position (usize::MAX when constrained).
348	    pub(crate) position: Vec<usize>,
349	    /// `order[k]`: the free position of the k-th ordered row.
350	    pub(crate) order: Vec<usize>,
351	    /// `rank[a]`: the ordered row of free position a.
352	    pub(crate) rank: Vec<usize>,
353	    /// First stored column of each ordered row.
354	    pub(crate) first: Vec<usize>,
355	    pub(crate) profile_entries: usize,
356	}
