358	/// RCM on the free–free sub-pattern (structural entries), and its skyline.
359	pub(crate) fn order_free(source: &PrimitiveSource, structure: &Structure) -> Ordering {
360	    let free = source.free_dofs();
361	    let mut position = vec![usize::MAX; source.dof_count()];
362	    for (a, &g) in free.iter().enumerate() {
363	        position[g] = a;
364	    }
365	    let adjacency: Vec<Vec<usize>> = free
366	        .iter()
367	        .map(|&g| {
368	            structure
369	                .pattern
370	                .row(g)
371	                .iter()
372	                .filter_map(|&c| (position[c] != usize::MAX && c != g).then_some(position[c]))
373	                .collect()
374	        })
375	        .collect();
376	    let order = reverse_cuthill_mckee(&adjacency);
377	    let mut rank = vec![0usize; free.len()];
378	    for (k, &a) in order.iter().enumerate() {
379	        rank[a] = k;
380	    }
381	    let first: Vec<usize> = order
382	        .iter()
383	        .enumerate()
384	        .map(|(i, &a)| {
385	            adjacency[a]
386	                .iter()
387	                .map(|&b| rank[b])
388	                .chain(std::iter::once(i))
389	                .min()
390	                .unwrap_or(i)
391	        })
392	        .collect();
393	    let profile_entries = first.iter().enumerate().map(|(i, &f)| i - f + 1).sum();
394	    Ordering {
395	        free,
396	        position,
397	        order,
398	        rank,
399	        first,
400	        profile_entries,
401	    }
402	}
