  1	//! K6's counting, capped global allocator (K6 plan §5; ROOT's K6 ruling N8).
  2	//!
  3	//! It is registered only by the observation binary and by the `k6_alloc`
  4	//! test binary, never by the harness library, so no consumer inherits it.
  5	//!
  6	//! - `CURRENT` is the requested bytes alive now. Two peaks are kept, both
  7	//!   deterministic for a given binary and input:
  8	//!   - `PEAK` (the in-place model): a growing `realloc` requests only the
  9	//!     difference, as the Mac gate's heap-cap probe counts it
 10	//!     (`T3/PLATFORM_CALIBRATION_MAC/gate/heap_cap_appended_to_p1_probe.rs.txt`).
 11	//!     The cap is enforced on this model;
 12	//!   - `PEAK_MOVE` (the move model): during a growing `realloc` the old and
 13	//!     the new block are alive together, as F1b's 24-byte estimate assumes.
 14	//! - `STAGE_PEAK` and `STAGE_PEAK_MOVE` restart at `stage_reset`.
 15	//! - A request that would take `CURRENT` above `CAP` is refused: a fixed
 16	//!   marker is written to fd 2 without allocating, and null is returned, so
 17	//!   Rust's allocation-error path aborts the process (SIGABRT). The marker
 18	//!   separates a heap-cap abort from an `RLIMIT_AS` failure, which prints only
 19	//!   Rust's own line.
 20	
 21	use std::alloc::{GlobalAlloc, Layout, System};
 22	use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
 23	
 24	static CURRENT: AtomicUsize = AtomicUsize::new(0);
 25	static PEAK: AtomicUsize = AtomicUsize::new(0);
 26	static PEAK_MOVE: AtomicUsize = AtomicUsize::new(0);
 27	static STAGE_PEAK: AtomicUsize = AtomicUsize::new(0);
 28	static STAGE_PEAK_MOVE: AtomicUsize = AtomicUsize::new(0);
 29	static CAP: AtomicUsize = AtomicUsize::new(usize::MAX);
 30	static CALLS: AtomicU64 = AtomicU64::new(0);
 31	
 32	/// The counting, capped allocator over `System`.
 33	pub struct K6Alloc;
 34	
 35	/// Sets the heap cap (requested bytes alive at once).
 36	pub fn set_cap(bytes: usize) {
 37	    CAP.store(bytes, Ordering::SeqCst);
 38	}
 39	pub fn cap() -> usize {
 40	    CAP.load(Ordering::SeqCst)
 41	}
 42	pub fn current() -> usize {
 43	    CURRENT.load(Ordering::SeqCst)
 44	}
 45	pub fn peak() -> usize {
 46	    PEAK.load(Ordering::SeqCst)
 47	}
 48	pub fn peak_move() -> usize {
 49	    PEAK_MOVE.load(Ordering::SeqCst)
 50	}
 51	pub fn stage_peak() -> usize {
 52	    STAGE_PEAK.load(Ordering::SeqCst)
 53	}
 54	pub fn stage_peak_move() -> usize {
 55	    STAGE_PEAK_MOVE.load(Ordering::SeqCst)
 56	}
 57	/// Allocation calls that succeeded (alloc, alloc_zeroed, realloc).
 58	#[allow(dead_code)] // observation binary (stage lines); unused by the k6_alloc test binary
 59	pub fn calls() -> u64 {
 60	    CALLS.load(Ordering::SeqCst)
 61	}
 62	/// Restarts the stage peaks at the current level.
 63	pub fn stage_reset() {
 64	    let now = current();
 65	    STAGE_PEAK.store(now, Ordering::SeqCst);
 66	    STAGE_PEAK_MOVE.store(now, Ordering::SeqCst);
 67	}
 68	/// Restarts every peak at the current level (tests only).
 69	#[allow(dead_code)] // k6_alloc test binary
 70	pub fn reset_peaks() {
 71	    let now = current();
 72	    PEAK.store(now, Ordering::SeqCst);
 73	    PEAK_MOVE.store(now, Ordering::SeqCst);
 74	    stage_reset();
 75	}
 76	
 77	fn note_peak(level: usize) {
 78	    PEAK.fetch_max(level, Ordering::SeqCst);
 79	    STAGE_PEAK.fetch_max(level, Ordering::SeqCst);
 80	    note_move(level);
 81	}
 82	
 83	fn note_move(level: usize) {
 84	    PEAK_MOVE.fetch_max(level, Ordering::SeqCst);
 85	    STAGE_PEAK_MOVE.fetch_max(level, Ordering::SeqCst);
 86	}
 87	
 88	/// Adds `bytes` to `CURRENT` unless that exceeds the cap; returns the new level.
 89	fn reserve(bytes: usize) -> Option<usize> {
 90	    let cap = cap();
 91	    let mut now = CURRENT.load(Ordering::SeqCst);
 92	    loop {
 93	        let next = now.checked_add(bytes)?;
 94	        if next > cap {
 95	            return None;
 96	        }
 97	        match CURRENT.compare_exchange_weak(now, next, Ordering::SeqCst, Ordering::SeqCst) {
 98	            Ok(_) => return Some(next),
 99	            Err(seen) => now = seen,
100	        }
101	    }
102	}
103	
104	fn release(bytes: usize) {
105	    CURRENT.fetch_sub(bytes, Ordering::SeqCst);
106	}
107	
108	/// Formats `value` in decimal into `buf` at `at`; returns the new end.
109	fn put_usize(buf: &mut [u8], mut at: usize, value: usize) -> usize {
110	    let mut digits = [0u8; 20];
111	    let mut n = value;
112	    let mut len = 0;
113	    loop {
114	        digits[len] = b'0' + (n % 10) as u8;
115	        len += 1;
116	        n /= 10;
117	        if n == 0 {
118	            break;
119	        }
120	    }
121	    for k in (0..len).rev() {
122	        if at < buf.len() {
123	            buf[at] = digits[k];
124	            at += 1;
125	        }
126	    }
127	    at
128	}
129	
130	fn put_bytes(buf: &mut [u8], mut at: usize, bytes: &[u8]) -> usize {
131	    for &b in bytes {
132	        if at < buf.len() {
133	            buf[at] = b;
134	            at += 1;
135	        }
136	    }
137	    at
138	}
139	
140	/// Writes `k6_observe: heap cap refused <size> bytes (current <c>, cap <cap>)`
141	/// to fd 2 from a stack buffer: no allocation.
142	fn refuse(size: usize) {
143	    let mut buf = [0u8; 160];
144	    let mut at = put_bytes(&mut buf, 0, b"k6_observe: heap cap refused ");
145	    at = put_usize(&mut buf, at, size);
146	    at = put_bytes(&mut buf, at, b" bytes (current ");
147	    at = put_usize(&mut buf, at, current());
148	    at = put_bytes(&mut buf, at, b", cap ");
149	    at = put_usize(&mut buf, at, cap());
150	    at = put_bytes(&mut buf, at, b")\n");
151	    write_stderr(&buf[..at]);
152	}
153	
154	#[cfg(unix)]
155	fn write_stderr(bytes: &[u8]) {
156	    use std::io::Write;
157	    use std::os::unix::io::FromRawFd;
158	    // SAFETY: fd 2 is the process's stderr; the `File` is forgotten, never
159	    // closed, and writing a byte slice does not allocate.
160	    let mut file = unsafe { std::fs::File::from_raw_fd(2) };
161	    let _ = file.write_all(bytes);
162	    std::mem::forget(file);
163	}
164	
165	#[cfg(not(unix))]
166	fn write_stderr(_bytes: &[u8]) {}
167	
168	unsafe impl GlobalAlloc for K6Alloc {
169	    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
170	        let size = layout.size();
171	        let Some(level) = reserve(size) else {
172	            refuse(size);
173	            return std::ptr::null_mut();
174	        };
175	        let ptr = System.alloc(layout);
176	        if ptr.is_null() {
177	            release(size);
178	        } else {
179	            note_peak(level);
180	            CALLS.fetch_add(1, Ordering::SeqCst);
181	        }
182	        ptr
183	    }
184	
185	    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
186	        let size = layout.size();
187	        let Some(level) = reserve(size) else {
188	            refuse(size);
189	            return std::ptr::null_mut();
190	        };
191	        let ptr = System.alloc_zeroed(layout);
192	        if ptr.is_null() {
193	            release(size);
194	        } else {
195	            note_peak(level);
196	            CALLS.fetch_add(1, Ordering::SeqCst);
197	        }
198	        ptr
199	    }
200	
201	    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
202	        System.dealloc(ptr, layout);
203	        release(layout.size());
204	    }
205	
206	    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
207	        let old = layout.size();
208	        if new_size > old {
209	            let Some(level) = reserve(new_size - old) else {
210	                refuse(new_size - old);
211	                return std::ptr::null_mut();
212	            };
213	            let moved = System.realloc(ptr, layout, new_size);
214	            if moved.is_null() {
215	                release(new_size - old);
216	            } else {
217	                note_peak(level);
218	                // The move model: the old block is alive beside the new one.
219	                note_move(level + old);
220	                CALLS.fetch_add(1, Ordering::SeqCst);
221	            }
222	            moved
223	        } else {
224	            let moved = System.realloc(ptr, layout, new_size);
225	            if !moved.is_null() {
226	                release(old - new_size);
227	                CALLS.fetch_add(1, Ordering::SeqCst);
228	            }
229	            moved
230	        }
231	    }
232	}

